slots.SLOT09:
// 教科書L16-4「ぶんけい」の表が正（Ⅱ p36: とります・よびます・聞きます・話します・待ちます・かえします・借ります・持ちます／
//   p37: 紹介・連絡・相談・説明・案内・用意）。追加: 送る・手伝う・知らせる（相手のために する 動作）
// とくべつ＝お〜にできない語だけ（L16-3 の語）。聞く→うかがいます・会う→お目にかかります は お〜 でも正しいので とくべつ に入れない
//   （聞く は お〜 として出題し ex で「うかがいます も ○」、会う は出題しない）
// m=ます形, ba=答え, g=1(お〜)/2(ご〜)/3(とくべつな ことば), ex=メモ(任意)。答えが2つの語は「／」でつなぐ（めくり・リズムでは2行に分ける）
// 表記は教科書の表どおり漢字＋ふりがな。漢字{よみ} 記法を R() で <span><ruby>…</ruby></span> に展開（.face の flex 直下に ruby を置かない）
function R(s){return '<span>'+s.replace(/([一-龥々]+)\{([^}]+)\}/g,'<ruby>$1<rt>$2</rt></ruby>')+'</span>';}
function BR(s){return s.replace('／','<br>');}
const KNAME={1:"お〜します",2:"ご〜します",3:"とくべつな ことば"};
const VERBS=[
  // 1=お〜します
  {m:R("とります"),ba:R("おとりします"),g:1},
  {m:R("よびます"),ba:R("およびします"),g:1},
  {m:R("聞{き}きます"),ba:R("お聞{き}きします"),g:1,ex:"うかがいます も ○"},
  {m:R("話{はな}します"),ba:R("お話{はな}しします"),g:1,ex:"「し」は のこる"},
  {m:R("待{ま}ちます"),ba:R("お待{ま}ちします"),g:1,ex:"うえの ひとが まつ なら お待ちになります"},
  {m:R("かえします"),ba:R("おかえしします"),g:1},
  {m:R("借{か}ります"),ba:R("お借{か}りします"),g:1},
  {m:R("持{も}ちます"),ba:R("お持{も}ちします"),g:1},
  {m:R("送{おく}ります"),ba:R("お送{おく}りします"),g:1},
  {m:R("手伝{てつだ}います"),ba:R("お手伝{てつだ}いします"),g:1},
  {m:R("知{し}らせます"),ba:R("お知{し}らせします"),g:1},
  // 2=ご〜します
  {m:R("紹介{しょうかい}します"),ba:R("ご紹介{しょうかい}します"),g:2},
  {m:R("連絡{れんらく}します"),ba:R("ご連絡{れんらく}します"),g:2},
  {m:R("相談{そうだん}します"),ba:R("ご相談{そうだん}します"),g:2},
  {m:R("説明{せつめい}します"),ba:R("ご説明{せつめい}します"),g:2},
  {m:R("案内{あんない}します"),ba:R("ご案内{あんない}します"),g:2},
  {m:R("用意{ようい}します"),ba:R("ご用意{ようい}します"),g:2},
  // 3=とくべつな ことば
  {m:R("行{い}きます"),ba:R("まいります／うかがいます"),g:3,ex:"こたえは 2つ"},
  {m:R("来{き}ます"),ba:R("まいります"),g:3},
  {m:R("見{み}ます"),ba:R("はいけんします"),g:3,ex:"×お見します"},
  {m:R("言{い}います"),ba:R("もうします"),g:3},
  {m:R("食{た}べます"),ba:R("いただきます"),g:3},
  {m:R("もらいます"),ba:R("いただきます"),g:3},
  {m:R("します"),ba:R("いたします"),g:3},
  {m:R("います"),ba:R("おります"),g:3}

